#!/usr/bin/env python3
"""Render the scoped proof with bundled KaTeX; no scientific claims inferred."""
from pathlib import Path
import re,html,markdown
HERE=Path(__file__).resolve().parent
source=(HERE/'antipodal-obstruction.md').read_text()
maths=[]
def token(tex,display=False):
 key='MATHPLACEHOLDER'+str(len(maths))+'END'
 tag='div' if display else 'span'
 maths.append((key,f'<{tag} class="math" data-tex="{html.escape(tex,quote=True)}" data-display="{str(display).lower()}">{html.escape(tex)}</{tag}>'))
 return '\n\n'+key+'\n\n' if display else key
source=re.sub(r'\\\[(.*?)\\\]',lambda m:token(m.group(1).strip(),True),source,flags=re.S)
def inline(m):
 value=m.group(1)
 if '.json' in value or '.py' in value or value.startswith('python '):return m.group(0)
 value=value.replace('exp(',r'\exp(')
 if '⟨{' in value:value=value.replace('{',r'\{').replace('}',r'\}')
 for a,b in {'θ':r'\theta ','π':r'\pi ','ρ':r'\rho ','Σ':r'\sum ','⟨':r'\langle ','⟩':r'\rangle ','±':r'\pm ','≠':r'\ne ','≤':r'\le ','≥':r'\ge ','×':r'\times ','−':'-','²':'^2','³':'^3','⁴':'^4','⁶':'^6','⁸':'^8','₃':'_3','₄':'_4','†':r'\dagger '}.items():value=value.replace(a,b)
 return token(value)
source=re.sub(r'`([^`]+)`',inline,source)
body=markdown.markdown(source,extensions=['tables'])
for key,value in maths:body=body.replace('<p>'+key+'</p>',value).replace(key,value)
intro='''<div class="status"><strong>Open in general</strong><span class="math" data-tex="2\\leq t_{\\max}(12,(2^4,1^4))\\leq3"></span><p>The proof below excludes a geometric subfamily. It does not prove maximum two for the full partition.</p></div>'''
extra='''<section><h2>An exact sequence explains the near-zero residuals</h2><div class="math" data-display="true" data-tex="P_\\epsilon(z)=(z^4-6z^2+1)^2[(z^2+1)^2+\\epsilon],\\qquad\\epsilon&gt;0"></div><p>Every positive parameter gives exactly four double and four simple roots: the quartic discriminants and their resultant are nonzero. As the parameter tends to zero, the normalized state approaches a third-order state with six double points. Thus the infimum of the third-order defect within the target partition is zero. This proves neither attainment nor nonattainment.</p><p><a href="boundary_sequence.json">Exact sequence certificate</a> · <a href="boundary_sequence.py">Verifier</a></p></section><section><h2>Additional constraints and searches</h2><p>For an arbitrary third-order candidate, every double point obeys a strict bound on its second Dicke probability in its pole frame:</p><div class="math" data-display="true" data-tex="\\frac{5}{14}&lt;|c_2|^2&lt;\\frac{19}{42}"></div><p>Distinct doubled points must also have angular separation greater than approximately 59.275637 degrees. These are necessary conditions, not a global exclusion.</p><p><a href="analytic-moment-constraints.json">Exact moment and separation certificates</a> · <a href="analytic-moment-constraints.py">Verifier</a></p><p>Searches in arbitrary complex star coordinates and symmetry-restricted polynomial families have not established a third-order state with the required eight distinct positions. Approaching the double octahedron changes the full partition and is not an attaining witness.</p><p><a href="search-summary.json">Search summary and limitations</a> · <a href="antipodal-obstruction-verification.json">Exact obstruction verification</a> · <a href="verify-antipodal-obstruction.py">Portable proof verifier</a> · <a href="antipodal-obstruction.md">Proof source</a></p></section>'''

rotations=r"""<section><h2>Threefold and fourfold symmetry are also impossible</h2><p>A threefold rotation forces one double pole, one simple pole and two three-point orbits. The Dicke support is <span class="math" data-tex="\{2,5,8,11\}"></span>, or its reflection. The first three uniform moments force probabilities</p><div class="math" data-display="true" data-tex="\left(\frac{37}{81},-\frac1{27},\frac{10}{27},\frac{17}{81}\right),"></div><p>which is impossible because one is negative.</p><p>A fourfold rotation instead gives <span class="math" data-tex="P(z)=(z^4-u)^2(z^4-v)"></span>. Third-order moments force the four Dicke probabilities to be <span class="math" data-tex="(5,11,11,5)/32"></span>. After making the polynomial monic, its endpoint coefficients have magnitude one and its two middle coefficients must each have magnitude 33. But a cubic <span class="math" data-tex="(w-u)^2(w-v)"></span> with these endpoint and equal-middle-magnitude conditions has middle magnitudes at most <span class="math" data-tex="\sqrt{9+6\sqrt3}&lt;5"></span>, a contradiction. This argument allows complex parameters.</p><p>Rotations of order five or more cannot preserve a set of four distinct double points: each nonaxial orbit would already contain at least five points.</p><p><a href="analytic-rotation-obstructions.json">Exact symmetry restrictions</a> · <a href="analytic-rotation-obstructions.py">Verifier</a> · <a href="boundary-and-rotation-independent-audit.json">Independent audit</a></p></section>"""

d2=r"""<section><h2>Two perpendicular half-turn axes are excluded</h2><p>The proper dihedral group <span class="math" data-tex="D_2"></span> is generated by half-turns about two perpendicular axes. Its doubled-point set is either two antipodal pairs, already excluded above, or one four-point orbit. In the latter case</p><div class="math" data-display="true" data-tex="Q(z)=z^4+az^2+1,\qquad a\in\mathbb C."></div><p>All residual quartics fall into four transformation classes: <span class="math" data-tex="R=\beta(z^4+1)+\gamma z^2"></span>, or a scalar multiple of <span class="math" data-tex="z^4-1"></span>, <span class="math" data-tex="z(z^2-1)"></span>, or <span class="math" data-tex="z(z^2+1)"></span>. The latter three classes have inconsistent exact AC equations.</p><p>In the two-dimensional class, normalize the nonzero <span class="math" data-tex="\beta"></span> to one and write <span class="math" data-tex="a=A+iB"></span>. Three AC equations determine the residual density matrix. Its determinant has the form <span class="math" data-tex="-12\mathcal P(A^2,B^2)/D(A,B)^2"></span>. Exact real-root counts certify positivity of every coefficient of the positive powers of <span class="math" data-tex="B^2"></span>; the constant coefficient is</p><div class="math" data-display="true" data-tex="\mathcal P(U,0)=U(U-36)^2(U+12)^6(2U^3+51U^2+1032U+3120)."></div><p>Hence a nonreal <span class="math" data-tex="a"></span> would require a negative density-matrix determinant. The real and vanishing-<span class="math" data-tex="\beta"></span> exceptions are checked separately; every survivor again has six double points.</p><p>Combining these exclusions, any hypothetical third-order state of the target partition must have proper rotational group <span class="math" data-tex="C_1"></span> or <span class="math" data-tex="C_2"></span>. These remaining cases are not excluded.</p><p><a href="analytic-d2-obstruction.json">Exact dihedral certificate</a> · <a href="analytic-d2-obstruction.py">Verifier</a></p></section>"""
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Twelve qubits, four double points · Partial exclusion</title><link rel="stylesheet" href="../../vendor/katex/katex.min.css"><script defer src="../../vendor/katex/katex.min.js"></script><style>body{margin:0;background:#f7f5ee;color:#28332f;font:17px/1.75 system-ui,sans-serif}main{max-width:960px;margin:45px auto;padding:0 28px 70px}h1,h2{font-family:Georgia,serif;line-height:1.25;color:#342d26}h1{font-size:2.2rem}h2{margin-top:2.4em}a{color:#814426;text-underline-offset:4px}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:.75rem;color:#814426}.status{border-left:4px solid #a76a2f;background:#eee8db;padding:18px 24px;margin:24px 0 36px}.status strong{display:block;color:#865b24}.status p{margin:8px 0 0}.status>.math{font-size:1.2rem}.math[data-display=true]{overflow-x:auto;max-width:100%;padding:10px 0}.katex-display{margin:.4em 0}code{font-size:.85em;overflow-wrap:anywhere}li{margin:.9em 0}footer{border-top:1px solid #ccc5b8;margin-top:35px;padding-top:15px;color:#68716c;font-size:.8rem}@media(max-width:600px){main{padding:0 18px}h1{font-size:1.75rem}body{font-size:16px}}</style><script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-tex]').forEach(el=>{el.innerHTML=katex.renderToString(el.dataset.tex,{displayMode:el.dataset.display==='true',throwOnError:false,strict:'ignore'});});});</script></head><body><main><p class="eyebrow">Majorana catalogue · Focused case study</p><a href="../../index.html#n=12&amp;partition=2-2-2-2-1-1-1-1&amp;state=partition-n12-2x4-1x4-tetra">← Return to the selected partition</a>'''+intro+body+rotations+d2+extra+'''<footer>Exact certificates checked independently. Numerical searches are evidence only; the full non-antipodal case remains open in this catalogue.</footer></main></body></html>'''
(HERE/'index.html').write_text(page)
print('Rendered scoped proof note.')
